        if isinstance(item, dict):
            return {k: v for k, v in ((key, process_item(val)) for key, val in item.items()) if v is not None}
        elif isinstance(item, list):
            return [process_item(v) for v in item if v is not None]
        else:
            return clean_value(item)

    processed_data = process_item(data)

