            for v in item.values():
                values.extend(flatten_values(v))
        elif isinstance(item, list):
            for v in item:
                values.extend(flatten_values(v))
        else:
            values.append(item)
        return values

    all_values = flatten_values(processed_data)
    value_counts = Counter(all_values)

    return {
        "data": processed_data,
        "value_counts": value_counts
    }
