            if isinstance(v, (int, float)):
                values.append(v)
            elif isinstance(v, str):
                try:
                    values.append(float(v))
                except (ValueError, TypeError):
                    continue
    elif isinstance(current, (int, float)):
        values = [current]
    elif isinstance(current, str):
        # Try to parse string as number or list of numbers
        try:
            values = [float(current)]
        except ValueError:
            # Try to parse as comma-separated numbers
            try:
                values = [float(x.strip()) for x in current.split(',') if x.strip()]
            except ValueError:
                raise ValueError("Data string is empty or corrupted - cannot parse as numeric")
    else:
        raise ValueError("No numeric data found at the specified path")

    # Check if we found any numeric data
    if len(values) == 0:
        raise ValueError("No numeric data found at the specified path")

    # Check for empty or corrupted data
    if all(v is None or (isinstance(v, float) and np.isnan(v)) for v in values):
        raise ValueError("Data string is empty or corrupted - all values are invalid")

    # Remove any NaN values
    values = [v for v in values if not (isinstance(v, float) and np.isnan(v))]

    if len(values) == 0:
        raise ValueError("No valid numeric data found after cleaning")

    # Create the boxplot
    fig, ax = plt.subplots(figsize=(8, 6))

    # Create a DataFrame for better plotting
    df = pd.DataFrame({'values': values})

    # Create boxplot using seaborn for better aesthetics
    sns.boxplot(data=df, y='values', ax=ax, color='skyblue')

    # Add individual data points (strip plot)
    sns.stripplot(data=df, y='values', ax=ax, color='darkblue', alpha=0.6, size=6)

    # Customize the plot
    ax.set_title(f'Boxplot of Data Values\nPath: {" → ".join(key_path)}', fontsize=14, fontweight='bold')
    ax.set_ylabel('Values', fontsize=12)
    ax.set_xlabel('', fontsize=12)
    ax.grid(True, alpha=0.3)

    # Add statistics text box
    stats_text = f'n = {len(values)}\nMean = {np.mean(values):.2f}\nMedian = {np.median(values):.2f}\nStd = {np.std(values):.2f}'
    ax.text(0.95, 0.95, stats_text, transform=ax.transAxes, fontsize=10,
            verticalalignment='top', horizontalalignment='right',
            bbox=dict(boxstyle='round', facecolor='wheat', alpha=0.5))

    plt.tight_layout()

    return fig
